
create database HospitalAnalyticsSystem;
USE HospitalAnalyticsSystem;

SET FOREIGN_KEY_CHECKS = 0;

CREATE TABLE Departments(
    DepartmentID INT AUTO_INCREMENT PRIMARY KEY,
    DepartmentName VARCHAR(100) NOT NULL UNIQUE,
    Description VARCHAR(255),
    Status ENUM('Active','Inactive') DEFAULT 'Active',
    CreatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE Doctors(
    DoctorID INT AUTO_INCREMENT PRIMARY KEY,
    DepartmentID INT NOT NULL,
    FirstName VARCHAR(50) NOT NULL,
    LastName VARCHAR(50) NOT NULL,
    Gender ENUM('Male','Female','Other'),
    Specialization VARCHAR(100),
    Qualification VARCHAR(100),
    ExperienceYears INT,
    Email VARCHAR(100) UNIQUE,
    Phone VARCHAR(15) UNIQUE,
    Salary DECIMAL(12,2),
    HireDate DATE,
    Status ENUM('Active','Inactive','On Leave') DEFAULT 'Active',
    CreatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_doctors_department
        FOREIGN KEY (DepartmentID) REFERENCES Departments(DepartmentID)
);

CREATE TABLE Patients(
    PatientID INT AUTO_INCREMENT PRIMARY KEY,
    FirstName VARCHAR(50) NOT NULL,
    LastName VARCHAR(50) NOT NULL,
    Gender ENUM('Male','Female','Other'),
    DOB DATE,
    BloodGroup VARCHAR(5),
    Phone VARCHAR(15) UNIQUE,
    Email VARCHAR(100) UNIQUE,
    Address VARCHAR(200),
    City VARCHAR(50),
    State VARCHAR(50),
    RegistrationDate DATE,
    Status ENUM('Active','Inactive','Deceased') DEFAULT 'Active',
    CreatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE InsuranceProviders(
    InsuranceID INT AUTO_INCREMENT PRIMARY KEY,
    ProviderName VARCHAR(100) NOT NULL UNIQUE,
    ContactNumber VARCHAR(15),
    CoveragePercent DECIMAL(5,2),
    Status ENUM('Active','Inactive') DEFAULT 'Active',
    CreatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE Rooms(
    RoomID INT AUTO_INCREMENT PRIMARY KEY,
    RoomNumber VARCHAR(20) NOT NULL UNIQUE,
    RoomType ENUM('General','Semi-Private','Private','ICU','Emergency') NOT NULL,
    DepartmentID INT,
    BedCapacity INT DEFAULT 1,
    DailyCharge DECIMAL(10,2),
    Status ENUM('Available','Occupied','Maintenance') DEFAULT 'Available',
    CreatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_rooms_department
        FOREIGN KEY (DepartmentID) REFERENCES Departments(DepartmentID)
);

CREATE TABLE Appointments(
    AppointmentID INT AUTO_INCREMENT PRIMARY KEY,
    PatientID INT NOT NULL,
    DoctorID INT NOT NULL,
    AppointmentDate DATETIME NOT NULL,
    AppointmentType ENUM('New','Follow-up','Emergency','Consultation') DEFAULT 'New',
    Status ENUM('Scheduled','Completed','Cancelled','No Show') DEFAULT 'Scheduled',
    CreatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_appointments_patient
        FOREIGN KEY (PatientID) REFERENCES Patients(PatientID),
    CONSTRAINT fk_appointments_doctor
        FOREIGN KEY (DoctorID) REFERENCES Doctors(DoctorID)
);

CREATE TABLE Visits(
    VisitID INT AUTO_INCREMENT PRIMARY KEY,
    AppointmentID INT,
    PatientID INT NOT NULL,
    DoctorID INT NOT NULL,
    DepartmentID INT NOT NULL,
    VisitDate DATETIME NOT NULL,
    VisitType ENUM('OPD','IPD','Emergency') DEFAULT 'OPD',
    ChiefComplaint VARCHAR(255),
    Status ENUM('Ongoing','Completed','Referred') DEFAULT 'Completed',
    CreatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_visits_appointment
        FOREIGN KEY (AppointmentID) REFERENCES Appointments(AppointmentID),
    CONSTRAINT fk_visits_patient
        FOREIGN KEY (PatientID) REFERENCES Patients(PatientID),
    CONSTRAINT fk_visits_doctor
        FOREIGN KEY (DoctorID) REFERENCES Doctors(DoctorID),
    CONSTRAINT fk_visits_department
        FOREIGN KEY (DepartmentID) REFERENCES Departments(DepartmentID)
);

CREATE TABLE Diagnoses(
    DiagnosisID INT AUTO_INCREMENT PRIMARY KEY,
    VisitID INT NOT NULL,
    DiagnosisName VARCHAR(150) NOT NULL,
    DiagnosisCode VARCHAR(20),
    Severity ENUM('Mild','Moderate','Severe','Critical') DEFAULT 'Mild',
    CreatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_diagnoses_visit
        FOREIGN KEY (VisitID) REFERENCES Visits(VisitID)
);

CREATE TABLE Treatments(
    TreatmentID INT AUTO_INCREMENT PRIMARY KEY,
    VisitID INT NOT NULL,
    DoctorID INT NOT NULL,
    TreatmentName VARCHAR(150) NOT NULL,
    TreatmentDate DATETIME NOT NULL,
    Cost DECIMAL(10,2) NOT NULL,
    CreatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_treatments_visit
        FOREIGN KEY (VisitID) REFERENCES Visits(VisitID),
    CONSTRAINT fk_treatments_doctor
        FOREIGN KEY (DoctorID) REFERENCES Doctors(DoctorID)
);

CREATE TABLE Prescriptions(
    PrescriptionID INT AUTO_INCREMENT PRIMARY KEY,
    VisitID INT NOT NULL,
    DoctorID INT NOT NULL,
    MedicineName VARCHAR(150) NOT NULL,
    Dosage VARCHAR(50),
    DurationDays INT,
    PrescriptionDate DATETIME NOT NULL,
    CreatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_prescriptions_visit
        FOREIGN KEY (VisitID) REFERENCES Visits(VisitID),
    CONSTRAINT fk_prescriptions_doctor
        FOREIGN KEY (DoctorID) REFERENCES Doctors(DoctorID)
);

CREATE TABLE LabTests(
    LabTestID INT AUTO_INCREMENT PRIMARY KEY,
    VisitID INT NOT NULL,
    TestName VARCHAR(150) NOT NULL,
    TestDate DATETIME NOT NULL,
    Result VARCHAR(255),
    Cost DECIMAL(10,2) NOT NULL,
    Status ENUM('Ordered','In Progress','Completed','Cancelled') DEFAULT 'Ordered',
    CreatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_labtests_visit
        FOREIGN KEY (VisitID) REFERENCES Visits(VisitID)
);

CREATE TABLE Admissions(
    AdmissionID INT AUTO_INCREMENT PRIMARY KEY,
    PatientID INT NOT NULL,
    RoomID INT NOT NULL,
    DoctorID INT NOT NULL,
    AdmissionDate DATETIME NOT NULL,
    DischargeDate DATETIME,
    Status ENUM('Admitted','Discharged','Transferred') DEFAULT 'Admitted',
    CreatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_admissions_patient
        FOREIGN KEY (PatientID) REFERENCES Patients(PatientID),
    CONSTRAINT fk_admissions_room
        FOREIGN KEY (RoomID) REFERENCES Rooms(RoomID),
    CONSTRAINT fk_admissions_doctor
        FOREIGN KEY (DoctorID) REFERENCES Doctors(DoctorID)
);

CREATE TABLE Billing(
    BillID INT AUTO_INCREMENT PRIMARY KEY,
    PatientID INT NOT NULL,
    VisitID INT,
    InsuranceID INT,
    BillDate DATETIME NOT NULL,
    TotalAmount DECIMAL(12,2) NOT NULL,
    InsuranceCovered DECIMAL(12,2) DEFAULT 0,
    PaidAmount DECIMAL(12,2) DEFAULT 0,
    PaymentStatus ENUM('Pending','Partially Paid','Paid') DEFAULT 'Pending',
    CreatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_billing_patient
        FOREIGN KEY (PatientID) REFERENCES Patients(PatientID),
    CONSTRAINT fk_billing_visit
        FOREIGN KEY (VisitID) REFERENCES Visits(VisitID),
    CONSTRAINT fk_billing_insurance
        FOREIGN KEY (InsuranceID) REFERENCES InsuranceProviders(InsuranceID)
);

CREATE TABLE Payments(
    PaymentID INT AUTO_INCREMENT PRIMARY KEY,
    BillID INT NOT NULL,
    PaymentDate DATETIME NOT NULL,
    Amount DECIMAL(12,2) NOT NULL,
    PaymentMode ENUM('Cash','Card','UPI','Insurance','Net Banking') DEFAULT 'Cash',
    CreatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_payments_bill
        FOREIGN KEY (BillID) REFERENCES Billing(BillID)
);

CREATE TABLE Feedback(
    FeedbackID INT AUTO_INCREMENT PRIMARY KEY,
    PatientID INT NOT NULL,
    DoctorID INT NOT NULL,
    VisitID INT,
    Rating INT,
    Comments VARCHAR(500),
    FeedbackDate DATETIME NOT NULL,
    CreatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_feedback_patient
        FOREIGN KEY (PatientID) REFERENCES Patients(PatientID),
    CONSTRAINT fk_feedback_doctor
        FOREIGN KEY (DoctorID) REFERENCES Doctors(DoctorID),
    CONSTRAINT fk_feedback_visit
        FOREIGN KEY (VisitID) REFERENCES Visits(VisitID),
    CONSTRAINT chk_feedback_rating
        CHECK (Rating BETWEEN 1 AND 5)
);




