-- Q1
SELECT FirstName, LastName, Email FROM Patients;

-- Q2
SELECT * FROM Doctors WHERE Salary > 120000;

-- Q3
SELECT * FROM Visits WHERE VisitType = 'Emergency' AND DepartmentID = 4;

-- Q4
SELECT * FROM Doctors ORDER BY DepartmentID ASC, LastName DESC;

-- Q5
SELECT DISTINCT City FROM Patients;

-- Q6
SELECT * FROM Doctors ORDER BY HireDate DESC LIMIT 5;

-- Q7
SELECT * FROM Visits WHERE VisitDate BETWEEN '2024-01-01' AND '2024-06-30';

-- Q8
SELECT * FROM Patients WHERE City IN ('Chennai','Coimbatore','Madurai');

-- Q9
SELECT * FROM Prescriptions WHERE MedicineName LIKE '%cin%';

-- Q10
SELECT * FROM Admissions WHERE DischargeDate IS NULL;

-- Q11
SELECT COUNT(*) AS TotalPatients FROM Patients;

-- Q12
SELECT AVG(Salary) AS AvgSalary, MIN(Salary) AS MinSalary, MAX(Salary) AS MaxSalary FROM Doctors;

-- Q13
SELECT DoctorID, FirstName, LastName, Salary, Salary * 12 AS AnnualSalary FROM Doctors;

-- Q14
SELECT v.VisitID, v.ChiefComplaint, d.DepartmentName
FROM Visits v
JOIN Departments d ON v.DepartmentID = d.DepartmentID;

-- Q15
UPDATE Patients SET Status = 'Inactive' WHERE PatientID = 12;
DELETE FROM Feedback WHERE FeedbackID = 99999;

-- Q16
SELECT d.DepartmentName, COUNT(v.VisitID) AS TotalVisits
FROM Departments d
LEFT JOIN Visits v ON d.DepartmentID = v.DepartmentID
GROUP BY d.DepartmentName;

-- Q17
SELECT DoctorID, COUNT(*) AS VisitCount
FROM Visits
GROUP BY DoctorID
HAVING COUNT(*) > 1;

-- Q18
SELECT v.VisitID,
       CONCAT(p.FirstName,' ',p.LastName) AS PatientName,
       CONCAT(doc.FirstName,' ',doc.LastName) AS DoctorName,
       d.DepartmentName
FROM Visits v
JOIN Patients p ON v.PatientID = p.PatientID
JOIN Doctors doc ON v.DoctorID = doc.DoctorID
JOIN Departments d ON v.DepartmentID = d.DepartmentID;

-- Q19
SELECT d.DepartmentName, COUNT(doc.DoctorID) AS DoctorCount
FROM Departments d
LEFT JOIN Doctors doc ON d.DepartmentID = doc.DepartmentID
GROUP BY d.DepartmentName;

-- Q20
SELECT MONTH(VisitDate) AS VisitMonth, COUNT(*) AS TotalVisits
FROM Visits
WHERE YEAR(VisitDate) = 2024
GROUP BY MONTH(VisitDate)
ORDER BY VisitMonth;


-- =====================================================================
-- SECTION 4: INTERMEDIATE LEVEL QUERIES
-- =====================================================================

-- Q21
SELECT doc.DoctorID, CONCAT(doc.FirstName,' ',doc.LastName) AS DoctorName,
       SUM(t.Cost) AS TotalRevenue
FROM Treatments t
JOIN Doctors doc ON t.DoctorID = doc.DoctorID
GROUP BY doc.DoctorID, DoctorName
ORDER BY TotalRevenue DESC
LIMIT 5;

-- Q22
SELECT PatientID, COUNT(DISTINCT DepartmentID) AS DeptCount
FROM Visits
GROUP BY PatientID
HAVING COUNT(DISTINCT DepartmentID) > 1;

-- Q23
SELECT d.DepartmentName, SUM(b.TotalAmount) AS Revenue
FROM Billing b
JOIN Visits v ON b.VisitID = v.VisitID
JOIN Departments d ON v.DepartmentID = d.DepartmentID
GROUP BY d.DepartmentName
ORDER BY Revenue DESC
LIMIT 1;

-- Q24
SELECT p.PatientID, CONCAT(p.FirstName,' ',p.LastName) AS PatientName, COUNT(v.VisitID) AS VisitCount
FROM Patients p
JOIN Visits v ON p.PatientID = v.PatientID
GROUP BY p.PatientID, PatientName
HAVING COUNT(v.VisitID) > 1;

-- Q25
SELECT PaymentMode, COUNT(*) AS UsageCount
FROM Payments
GROUP BY PaymentMode
ORDER BY UsageCount DESC
LIMIT 1;

-- Q26
SELECT doc.DoctorID, CONCAT(doc.FirstName,' ',doc.LastName) AS DoctorName,
       AVG(f.Rating) AS AvgRating
FROM Feedback f
JOIN Doctors doc ON f.DoctorID = doc.DoctorID
GROUP BY doc.DoctorID, DoctorName
HAVING AVG(f.Rating) > 4.0;

-- Q27
SELECT DepartmentName, VisitCount FROM (
    SELECT d.DepartmentName, COUNT(v.VisitID) AS VisitCount,
           DENSE_RANK() OVER (ORDER BY COUNT(v.VisitID) DESC) AS rnk
    FROM Departments d
    JOIN Visits v ON d.DepartmentID = v.DepartmentID
    GROUP BY d.DepartmentName
) ranked
WHERE rnk = 2;

-- Q28
SELECT p.PatientID, CONCAT(p.FirstName,' ',p.LastName) AS PatientName,
       SUM(CASE WHEN v.VisitType = 'Emergency' THEN 1 ELSE 0 END) AS EmergencyVisits,
       COUNT(*) AS TotalVisits
FROM Visits v
JOIN Patients p ON v.PatientID = p.PatientID
GROUP BY p.PatientID, PatientName
HAVING SUM(CASE WHEN v.VisitType = 'Emergency' THEN 1 ELSE 0 END) * 1.0 / COUNT(*) >= 0.5;

-- Q29
SELECT d.DepartmentName,
       AVG(DATEDIFF(a.DischargeDate, a.AdmissionDate)) AS AvgStayDays
FROM Admissions a
JOIN Doctors doc ON a.DoctorID = doc.DoctorID
JOIN Departments d ON doc.DepartmentID = d.DepartmentID
WHERE a.DischargeDate IS NOT NULL
GROUP BY d.DepartmentName;

-- Q30
SELECT City, COUNT(*) AS PatientCount
FROM Patients
GROUP BY City
ORDER BY PatientCount DESC
LIMIT 5;

-- Q31
SELECT TestName, COUNT(DISTINCT VisitID) AS VisitCount
FROM LabTests
GROUP BY TestName
HAVING COUNT(DISTINCT VisitID) > 2;

-- Q32
SELECT v.VisitID, v.PatientID
FROM Visits v
LEFT JOIN Feedback f ON v.VisitID = f.VisitID
WHERE v.Status = 'Completed' AND f.FeedbackID IS NULL;

-- Q33
SELECT FirstName, LastName, Phone, COUNT(*) AS DupCount
FROM Patients
GROUP BY FirstName, LastName, Phone
HAVING COUNT(*) > 1;

-- Q34
SELECT doc.DoctorID, CONCAT(doc.FirstName,' ',doc.LastName) AS DoctorName,
       SUM(t.Cost) AS DoctorRevenue,
       ROUND(SUM(t.Cost) * 100.0 / (SELECT SUM(Cost) FROM Treatments), 2) AS PctContribution
FROM Treatments t
JOIN Doctors doc ON t.DoctorID = doc.DoctorID
GROUP BY doc.DoctorID, DoctorName
ORDER BY PctContribution DESC;

-- Q35
SELECT d.DepartmentName,
       SUM(b.TotalAmount) AS DeptRevenue,
       ROUND(SUM(b.TotalAmount) * 100.0 / (SELECT SUM(TotalAmount) FROM Billing), 2) AS PctContribution
FROM Billing b
JOIN Visits v ON b.VisitID = v.VisitID
JOIN Departments d ON v.DepartmentID = d.DepartmentID
GROUP BY d.DepartmentName
ORDER BY PctContribution DESC;

-- Q36
SELECT doc.DoctorID, CONCAT(doc.FirstName,' ',doc.LastName) AS DoctorName,
       COUNT(DISTINCT v.VisitID) AS TotalVisits,
       COALESCE(SUM(t.Cost),0) AS TotalRevenue,
       ROUND(AVG(f.Rating),2) AS AvgRating,
       RANK() OVER (ORDER BY COUNT(DISTINCT v.VisitID) DESC) AS PerformanceRank
FROM Doctors doc
LEFT JOIN Visits v ON doc.DoctorID = v.DoctorID
LEFT JOIN Treatments t ON doc.DoctorID = t.DoctorID
LEFT JOIN Feedback f ON doc.DoctorID = f.DoctorID
GROUP BY doc.DoctorID, DoctorName;

-- Q37
SELECT d.DepartmentName, AVG(b.TotalAmount) AS AvgRevenuePerVisit
FROM Billing b
JOIN Visits v ON b.VisitID = v.VisitID
JOIN Departments d ON v.DepartmentID = d.DepartmentID
GROUP BY d.DepartmentName
HAVING AVG(b.TotalAmount) > (SELECT AVG(TotalAmount) FROM Billing);

-- Q38
SELECT dg.DiagnosisName, CONCAT(p.FirstName,' ',p.LastName) AS PatientName,
       CONCAT(doc.FirstName,' ',doc.LastName) AS DoctorName, dept.DepartmentName
FROM Diagnoses dg
JOIN Visits v ON dg.VisitID = v.VisitID
JOIN Patients p ON v.PatientID = p.PatientID
JOIN Doctors doc ON v.DoctorID = doc.DoctorID
JOIN Departments dept ON v.DepartmentID = dept.DepartmentID
WHERE dg.Severity = 'Critical' AND v.Status != 'Completed';

-- Q39
SELECT dept.DepartmentName, v.VisitType, COUNT(*) AS TotalVisits
FROM Visits v
JOIN Departments dept ON v.DepartmentID = dept.DepartmentID
GROUP BY dept.DepartmentName, v.VisitType
ORDER BY dept.DepartmentName, v.VisitType;

-- Q40
CREATE VIEW vw_VisitSummary AS
SELECT v.VisitID,
       CONCAT(p.FirstName,' ',p.LastName) AS PatientName,
       CONCAT(doc.FirstName,' ',doc.LastName) AS DoctorName,
       d.DepartmentName,
       v.Status
FROM Visits v
JOIN Patients p ON v.PatientID = p.PatientID
JOIN Doctors doc ON v.DoctorID = doc.DoctorID
JOIN Departments d ON v.DepartmentID = d.DepartmentID;

-- Test the view:
SELECT * FROM vw_VisitSummary LIMIT 20;


-- =====================================================================
-- SECTION 5: ADVANCED SQL (WINDOW FUNCTIONS, CTEs, PROCEDURES, TRIGGERS)
-- =====================================================================

-- Q41
SELECT doc.DoctorID, doc.FirstName, doc.LastName, dept.DepartmentName,
       SUM(t.Cost) AS TotalRevenue,
       RANK() OVER (PARTITION BY dept.DepartmentID ORDER BY SUM(t.Cost) DESC) AS RevenueRank
FROM Treatments t
JOIN Doctors doc ON t.DoctorID = doc.DoctorID
JOIN Departments dept ON doc.DepartmentID = dept.DepartmentID
GROUP BY doc.DoctorID, doc.FirstName, doc.LastName, dept.DepartmentID, dept.DepartmentName;

-- Q42
SELECT VisitID, PatientID, VisitDate FROM (
    SELECT v.*, ROW_NUMBER() OVER (PARTITION BY v.PatientID ORDER BY v.VisitDate DESC) AS rn
    FROM Visits v
) ranked
WHERE rn = 1;

-- Q43
SELECT DATE(BillDate) AS BillDay,
       SUM(TotalAmount) AS DailyRevenue,
       SUM(SUM(TotalAmount)) OVER (ORDER BY DATE(BillDate)) AS RunningRevenue
FROM Billing
GROUP BY DATE(BillDate)
ORDER BY BillDay;

-- Q44
WITH MonthlyRevenue AS (
    SELECT DATE_FORMAT(BillDate, '%Y-%m') AS BillMonth,
           SUM(TotalAmount) AS Revenue
    FROM Billing
    GROUP BY DATE_FORMAT(BillDate, '%Y-%m')
)
SELECT
    BillMonth,
    Revenue AS MonthlyRevenue,
    LAG(Revenue) OVER (ORDER BY BillMonth) AS PrevMonthRevenue,
    Revenue - LAG(Revenue) OVER (ORDER BY BillMonth) AS RevenueChange
FROM MonthlyRevenue
ORDER BY BillMonth;

-- Q45
WITH DeptRevenue AS (
    SELECT v.DepartmentID, SUM(b.TotalAmount) AS Revenue
    FROM Billing b
    JOIN Visits v ON b.VisitID = v.VisitID
    GROUP BY v.DepartmentID
)
SELECT d.DepartmentName, dr.Revenue
FROM DeptRevenue dr
JOIN Departments d ON dr.DepartmentID = d.DepartmentID
ORDER BY dr.Revenue DESC
LIMIT 5;

-- Q46
SELECT doc.DoctorID, doc.FirstName, doc.LastName, COUNT(v.VisitID) AS VisitCount
FROM Doctors doc
JOIN Visits v ON doc.DoctorID = v.DoctorID
GROUP BY doc.DoctorID, doc.FirstName, doc.LastName
HAVING COUNT(v.VisitID) > ALL (
    SELECT COUNT(v2.VisitID)
    FROM Doctors doc2
    JOIN Departments d ON doc2.DepartmentID = d.DepartmentID
    JOIN Visits v2 ON doc2.DoctorID = v2.DoctorID
    WHERE d.DepartmentName = 'General Medicine'
    GROUP BY doc2.DoctorID
);

-- Q47
SELECT d.DepartmentName,
       SUM(CASE WHEN v.VisitType = 'OPD' THEN 1 ELSE 0 END) AS OPD_Visits,
       SUM(CASE WHEN v.VisitType = 'IPD' THEN 1 ELSE 0 END) AS IPD_Visits,
       SUM(CASE WHEN v.VisitType = 'Emergency' THEN 1 ELSE 0 END) AS Emergency_Visits
FROM Visits v
JOIN Departments d ON v.DepartmentID = d.DepartmentID
GROUP BY d.DepartmentName
ORDER BY d.DepartmentName;

-- Q48
DELIMITER $$

CREATE PROCEDURE GetPatientVisitHistory(IN p_PatientID INT)
BEGIN
    SELECT v.VisitID, v.VisitDate, CONCAT(doc.FirstName,' ',doc.LastName) AS DoctorName,
           d.DepartmentName, v.ChiefComplaint, v.Status
    FROM Visits v
    JOIN Doctors doc ON v.DoctorID = doc.DoctorID
    JOIN Departments d ON v.DepartmentID = d.DepartmentID
    WHERE v.PatientID = p_PatientID
    ORDER BY v.VisitDate DESC;
END$$

DELIMITER ;

-- Usage:
-- CALL GetPatientVisitHistory(1);

-- Q49
DELIMITER $$

CREATE TRIGGER trg_UpdatePaymentStatus
AFTER INSERT ON Payments
FOR EACH ROW
BEGIN
    DECLARE v_TotalAmount DECIMAL(12,2);
    DECLARE v_TotalPaid DECIMAL(12,2);

    SELECT TotalAmount INTO v_TotalAmount FROM Billing WHERE BillID = NEW.BillID;
    SELECT COALESCE(SUM(Amount),0) INTO v_TotalPaid FROM Payments WHERE BillID = NEW.BillID;

    UPDATE Billing
    SET PaidAmount = v_TotalPaid,
        PaymentStatus = CASE
            WHEN v_TotalPaid >= v_TotalAmount THEN 'Paid'
            WHEN v_TotalPaid > 0 THEN 'Partially Paid'
            ELSE 'Pending'
        END
    WHERE BillID = NEW.BillID;
END$$

DELIMITER ;

-- Q50
DROP PROCEDURE IF EXISTS AdmitPatient;
DELIMITER $$

CREATE PROCEDURE AdmitPatient(
    IN p_PatientID INT,
    IN p_RoomID INT,
    IN p_DoctorID INT
)
BEGIN
    DECLARE roomStatus VARCHAR(20);

    SELECT Status INTO roomStatus FROM Rooms WHERE RoomID = p_RoomID;

    IF roomStatus IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Room Not Found';
    ELSEIF roomStatus = 'Available' THEN
        START TRANSACTION;

        INSERT INTO Admissions (PatientID, RoomID, DoctorID, AdmissionDate, Status)
        VALUES (p_PatientID, p_RoomID, p_DoctorID, NOW(), 'Admitted');

        UPDATE Rooms SET Status = 'Occupied' WHERE RoomID = p_RoomID;

        COMMIT;
    ELSE
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Prohibited: Room Not Available';
    END IF;
END$$

DELIMITER ;

